
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_gap_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_gap", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.162678196921155e+00, -5.068997365455051e+00, -4.937539621447613e+00, -4.754955301987256e+00, -4.504849076775684e+00, -4.168170107516771e+00, -3.723036210282001e+00, -3.138570009181220e+00, -2.356755558923185e+00, -1.385589031181307e+00, -6.651458274049886e-01, -5.272963094810531e-01, -6.458920955955981e-01, -5.614119814515754e-01, -3.577914841103541e-01, -1.540402415442353e-01, -5.266643024787227e-02, -1.613817327297525e-02, -3.432935095807245e-03, -3.864354842990789e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


